const forms=document.querySelectorAll("form[data-search]");if(typeof WebAssembly=="object")for(const e of forms)e.action=e.dataset.search,e.querySelector('input[name="sites"]')?.remove();const results=document.querySelector("[data-search-results]"),query=new URLSearchParams(location.search).get("q")?.trim();results&&query&&showResults(forms[forms.length-1],results,query);async function showResults(e,t,n){const s=document.querySelector("[data-search-status]");for(const e of document.querySelectorAll('input[name="q"]'))e.value=n;s.textContent=s.dataset.searching;try{const o=await import(e.dataset.pagefind+"pagefind.js");await o.options({baseUrl:e.dataset.base});const i=await o.search(n),a=await Promise.all(i.results.slice(0,30).map(e=>e.data())),r=a.length?s.dataset.found:s.dataset.none;s.textContent=r.replace("{count}",i.results.length).replace("{query}",n);for(const e of a){const s=document.createElement("li"),n=document.createElement("a");n.href=e.url,n.textContent=e.meta.title;const o=document.createElement("p");o.innerHTML=e.excerpt,s.append(n,o),t.append(s)}}catch{const t=new URL("https://duckduckgo.com/");t.searchParams.set("q",n),t.searchParams.set("sites",e.dataset.sites),location.replace(t)}}